const cfg = Object.fromEntries($('Config').all().map(i => [i.json.key, i.json.value]));
const e = $('Error Trigger').first().json;

// В алерт не должны попасть ключи: маскируем вебхуки Битрикса, токены ботов и API-ключи
const mask = (s) => String(s ?? '')
  .replace(/\/rest\/\d+\/[A-Za-z0-9]+/g, '/rest/***')
  .replace(/\d{6,}:[A-Za-z0-9_-]{30,}/g, '***')
  .replace(/sk-[A-Za-z0-9_-]{20,}/g, 'sk-***');
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const exec = e.execution || {};
const err = exec.error || e.trigger?.error || {};
const text = [
  '🚨 <b>HELIOS: ошибка автоматизации</b>',
  `Workflow: ${esc(e.workflow?.name ?? '—')}`,
  `Нода: ${esc(exec.lastNodeExecuted ?? err.node?.name ?? '—')}`,
  `Ошибка: ${esc(mask(err.message || 'unknown').slice(0, 800))}`,
  err.description ? `Детали: ${esc(mask(err.description).slice(0, 800))}` : null,
  `Execution: ${esc(exec.url ?? (exec.id ? 'id ' + exec.id : '—'))}`,
].filter(Boolean).join('\n');

return [{ json: { chatId: cfg.manager_chat_id, text } }];
